const D = { energy: .55, scale: 1, density: .55, speed: 1, fog: .6, swell: .5, hue: 196, x: .5, y: .66, style: 'haar', act: 'lift', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 196;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];
const NL = 4;                                  // depth planes: 0 = farthest, 3 = nearest

// ---------------- style = a different way of building form, not a hue swap ----------------
const STY = {
  // North Atlantic haar: cold desaturated grey-green, modelled rock, real aerial perspective
  haar:       { skyT:[203,22,52], skyL:[196,10,74], rock:[205,14,30], lit:[38,8,52], sea:[199,16,44],
                foam:[190,4,92], fogC:[196,7,84], hatch:0, wire:0, flat:0, grain:22 },
  // wet-collodion dry plate: warm grey, blown highlights, plate flaws, hard vignette
  dryplate:   { skyT:[36,10,58], skyL:[38,14,84], rock:[34,14,26], lit:[40,12,58], sea:[34,10,42],
                foam:[42,5,95], fogC:[38,8,88], hatch:0, wire:0, flat:0, grain:52 },
  // ABSTRACTED: woodblock — flat tonal planes, hard edges, no modelling inside a plane
  ukiyo:      { skyT:[30,16,84], skyL:[28,10,92], rock:[212,26,34], lit:[210,20,52], sea:[206,34,54],
                foam:[35,4,97], fogC:[32,6,93], hatch:0, wire:0, flat:1, grain:10 },
  // ABSTRACTED: x-ray / wireframe — the columnar jointing as a transparent lattice, no mass
  xray:       { skyT:[218,62,19], skyL:[216,52,27], rock:[186,44,74], lit:[184,30,94], sea:[210,46,26],
                foam:[184,26,96], fogC:[196,40,34], hatch:0, wire:1, flat:0, grain:6 },
  // graphite: soft pencil study — tone built entirely from hatching, no colour
  graphite:   { skyT:[40,3,72], skyL:[40,2,86], rock:[40,4,32], lit:[40,3,56], sea:[40,3,50],
                foam:[40,1,92], fogC:[40,2,88], hatch:1, wire:0, flat:0, grain:34 }
};
const st = STY[P.style] || STY.haar;

const hy = height * P.y;
const en = Math.max(0, Math.min(1, P.energy));
const fg = Math.max(0, Math.min(1, P.fog));
const ty0 = Math.max(0, hy - u * .58);
const bh = Math.max(4, Math.ceil(hy + u * .20 - ty0));
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.planes.forEach(p => p.remove()); S.fog0.remove(); S.fog1.remove(); }
  S.sky = mk(W, H);
  S.planes = []; for (let L = 0; L < NL; L++) S.planes.push(mk(W, bh));
  S.fog0 = mk(W, bh); S.fog1 = mk(W, bh);

  // --- sky: value climbs toward the horizon (fog-lit, no blue dome) ---
  const g = S.sky; g.noStroke();
  const cT = sh(st.skyT), cL = sh(st.skyL);
  for (let yy = 0; yy < H; yy++) {
    const f = Math.pow(Math.min(1, yy / Math.max(1, hy)), .8);
    const c = L3(cT, cL, f);
    g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1);
  }

  // --- the stacks: silhouette EMERGES from columnar basalt jointing, never a flat blob ---
  const rockC = sh(st.rock), litC = sh(st.lit), fogC = sh(st.fogC);
  for (let L = 0; L < NL; L++) {
    const q = S.planes[L];
    const near = L / (NL - 1);                       // 0 far -> 1 near
    const hazeF = (1 - near) * (.30 + .58 * fg);     // far planes dissolve into the fog colour
    const base = L3(rockC, fogC, hazeF);
    const litB = L3(litC, fogC, hazeF * .9);
    const nstk = Math.max(1, Math.round((1 + fr(L * 13 + 1) * 2.2) * (.5 + P.density)) + (L < 2 ? 1 : 0));
    const seaY = hy - ty0 + (near - .5) * u * .012;  // nearer stacks meet the water lower
    for (let s = 0; s < nstk; s++) {
      const id = L * 97 + s * 17;
      const sx = W * ((s + .5 + (fr(id + 2) - .5) * .7) / nstk);
      const hgt = u * (.10 + .34 * near + fr(id + 3) * .16) * P.scale;
      const wid = hgt * (.24 + fr(id + 4) * .30);
      const lean = (fr(id + 5) - .5) * .10;
      const ncol = Math.max(4, Math.floor(wid / Math.max(1.6, u * .0075 * P.scale)));
      for (let c = 0; c < ncol; c++) {
        const fx = (c + .5) / ncol;
        const env = Math.pow(Math.sin(Math.PI * Math.min(.999, Math.max(.001, fx))), .30);   // flat-topped, sloped shoulders
        const jag = .74 + .26 * (fr(id * 31 + c * 7) * .6 + fr(id * 13 + c * 3 + 1) * .4);
        const ch = hgt * env * jag;
        const cw = wid / ncol;
        const cxp = sx - wid / 2 + c * cw;
        const topY = seaY - ch;
        // per-column shading: light rakes across the face, so the column IS the texture
        const lam = .55 + .45 * Math.cos((fx - (P.x * .8 + .1)) * 2.6);
        const jit = (fr(id * 7 + c * 11 + 5) - .5) * 12;
        const col = L3(base, litB, Math.max(0, Math.min(1, lam * (.55 + .45 * near))));
        if (st.wire) {
          q.noFill(); q.strokeWeight(Math.max(.5, u * .0011));
          q.stroke(col[0], col[1], Math.min(99, col[2] + 24), 22 + 40 * near);
          q.rect(cxp, topY, cw, ch);
          q.line(cxp, topY + ch * .34, cxp + cw, topY + ch * .30 + jit * .4);
          q.line(cxp, topY + ch * .68, cxp + cw, topY + ch * .72 + jit * .4);
        } else {
          q.noStroke();
          q.fill(col[0], col[1], Math.max(2, col[2] + (st.flat ? 0 : jit)), 100);
          q.quad(cxp, topY, cxp + cw + .8, topY + (fr(id + c) - .5) * ch * .05,
                 cxp + cw + .8 + lean * ch, seaY + 2, cxp + lean * ch, seaY + 2);
          if (!st.flat) {                          // the joint shadow between columns
            q.stroke(base[0], base[1] + 6, Math.max(1, base[2] * .62), 46);
            q.strokeWeight(Math.max(.4, cw * .10)); q.line(cxp, topY + 1, cxp + lean * ch, seaY);
            q.noStroke();
          }
        }
      }
      if (st.hatch) {                              // graphite: tone is hatching, nothing else
        q.strokeWeight(Math.max(.4, u * .0009));
        for (let hI = 0; hI < 90; hI++) {
          const hx = sx - wid / 2 + fr(id * 5 + hI) * wid;
          const hyy = seaY - fr(id * 3 + hI * 2) * hgt * .9;
          q.stroke(base[0], base[1], Math.max(2, base[2] - 14), 22 + fr(hI) * 26);
          q.line(hx, hyy, hx + u * .012, hyy + u * .012);
        }
        q.noStroke();
      }
      // reflection smeared into the water, faded and vertically stretched
      if (!st.wire) {
        q.noStroke();
        for (let r = 0; r < 12; r++) {
          const rf = r / 12;
          q.fill(base[0], base[1] * .8, Math.max(2, base[2] * (.66 - rf * .3)), (30 - rf * 26) * (.4 + .6 * near));
          q.rect(sx - wid * (.5 + rf * .12), seaY + rf * u * .016, wid * (1 + rf * .24), u * .018);
        }
      }
    }
    // per-plane haze veil — the aerial-perspective plane separator
    q.noStroke(); q.fill(fogC[0], fogC[1], fogC[2], (1 - near) * (10 + 30 * fg));
    q.rect(0, 0, W, bh);
  }

  // --- two tileable fog banks (blobs drawn 3x so a linear scroll never seams) ---
  const fogC2 = sh(st.fogC);
  for (const [gg, n, yc, spr, thk, alp] of [[S.fog0, 11, hy - ty0 - u * .10, u * .30, u * .075, 15],
                                            [S.fog1, 8, hy - ty0 - u * .01, u * .16, u * .045, 22]]) {
    gg.noStroke();
    for (let i = 0; i < n; i++) {
      const bx = fr(i * 5 + 61) * W;
      const by = yc + (fr(i * 5 + 62) - .5) * spr;
      const bw = u * (.22 + fr(i * 5 + 63) * .70);
      const bhh = thk * (.5 + fr(i * 5 + 64) * 1.0);
      for (let rep = -1; rep <= 1; rep++)
        for (let k = 0; k < 4; k++) {
          gg.fill(fogC2[0], fogC2[1] * (1 - k * .1), Math.min(99, fogC2[2] + k * 2), alp * (1 - k * .2));
          gg.ellipse(bx + rep * W, by + k * bhh * .14, bw * (1 - k * .12), bhh * (1 - k * .08));
        }
    }
  }
  S.key = key;
}

// ---------------- act: what the weather is doing over minutes ----------------
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = { lift: { f: 1.05 - sec * .09, sw: .9 }, close: { f: .35 + sec * .09, sw: 1 }, gale: { f: .7, sw: 1.5 + sec * .07 } };
const act = ACT[P.act] || ACT.lift;
const fogAmt = Math.max(.05, Math.min(1.4, act.f));
const swAmt = Math.max(0, Math.min(1, P.swell)) * act.sw;

// ---------------- composite: sky / far planes / fog between them / sea ----------------
noStroke();
image(S.sky, 0, 0);

const W2 = S.fog0.width;
const scr = (g, px, yy, a) => { const ox = ((px % W2) + W2) % W2; if (a < 100) tint(0, 0, 100, a); image(g, ox - W2, yy); image(g, ox, yy); if (a < 100) noTint(); };

// far half of the fog sits BEHIND the near stacks — that's what makes the depth read
scr(S.fog0, -K.t * u * .0035 * P.speed, ty0, 100 * Math.min(1, fogAmt));
for (let L = 0; L < NL; L++) {
  const near = L / (NL - 1);
  // slow camera drift: each plane on its own incommensurate rate, nearer = larger throw
  const dx = (Math.sin(K.t * (.021 + L * .0074) + L * 1.9) * .7 + Math.sin(K.t * (.047 + L * .011) + L) * .3) * u * .012 * (.25 + near) * P.speed;
  const dy = Math.sin(K.t * (.017 + L * .006) + L * 2.7) * u * .0025 * (.2 + near);
  image(S.planes[L], dx, ty0 + dy);
  if (L === 1) scr(S.fog1, -K.t * u * .0091 * P.speed - u * .4, ty0 + u * .01, 100 * Math.min(1, fogAmt * .9));
}

// ---------------- sea: live swell, compressed toward the horizon ----------------
const seaC = sh(st.sea), foamC = sh(st.foam), fogC3 = sh(st.fogC);
if (!st.wire) { fill(seaC[0], seaC[1], seaC[2]); rect(0, hy, width, height - hy); }
else { noFill(); stroke(seaC[0], seaC[1], seaC[2] + 30, 40); strokeWeight(1); rect(0, hy, width, height - hy); noStroke(); }

const nsw = Math.floor(26 + P.density * 26);
noFill();
for (let i = 0; i < nsw; i++) {
  const f = Math.pow((i + .5) / nsw, 2.0);
  const yy = hy + f * (height - hy);
  const d = Math.max(.02, f);
  // three incommensurate real-time terms per line: the swell never re-phases at 8 s
  const ph = K.t * (.31 + d * .55) * P.speed;
  const amp = u * .010 * d * (.35 + swAmt) * (.6 + .4 * en);
  strokeWeight(Math.max(.6, u * .0016 * (.3 + d * 2.2)));
  const v = seaC[2] * (.72 + .5 * d) + (st.flat ? 0 : 10 * Math.sin(i * 1.7));
  stroke(seaC[0], seaC[1] * (.6 + .4 * d), Math.min(99, v + 10), 30 + 34 * d);
  beginShape();
  for (let xx = -10; xx <= width + 10; xx += Math.max(7, 16 * d)) {
    const w1 = Math.sin(xx * .0075 / (1 + d) + ph) * .7 + Math.sin(xx * .019 / (1 + d) - ph * 1.43 + i) * .35 + Math.sin(xx * .0031 + K.t * .229) * .5;
    vertex(xx, yy + w1 * amp);
  }
  endShape();
}
noStroke();
// horizon haze plane — sea and sky must meet in value, not in a hard line
for (let i = 0; i < 4; i++) {
  const dr = Math.sin(K.t * (.037 + i * .019) + i * 2.3) * .5 + .5;
  fill(fogC3[0], fogC3[1], fogC3[2], (6 + 12 * fg) * Math.min(1, fogAmt) * (1 - i * .17));
  rect(0, hy - u * (.03 + i * .012) - dr * u * .008, width, u * (.055 + i * .05));
}

// --- wash at the stack bases: the only place the sea breaks white ---
if (!st.wire) {
  const nw = Math.floor(6 + P.density * 8);
  for (let i = 0; i < nw; i++) {
    const bx = fr(i * 11 + 401) * width;
    const by = hy + Math.pow(fr(i * 11 + 402), 1.5) * (height - hy) * .5;
    const dd = (by - hy) / Math.max(1, height - hy);
    // clk baseline first, audio only added on top — silence must still surge
    const surge = .5 + .5 * Math.sin(K.t * (.53 + i * .07) + i * 2.1) * .6 + .3 * Math.sin(K.t * 1.19 + i);
    const amp2 = Math.max(0, surge) * (.4 + .6 * swAmt) + K.swell * .18 + A.bass * .28;
    fill(foamC[0], foamC[1], foamC[2], (14 + 30 * amp2) * (.35 + .65 * en) * (.4 + dd));
    ellipse(bx, by, u * (.05 + .12 * amp2) * (.4 + dd * 1.6), u * .012 * (.3 + dd * 1.4));
  }
}

// --- grain / plate flaws: texture over every flat area ---
if (st.grain > 12) {
  const ng = Math.floor(st.grain * 5);
  for (let i = 0; i < ng; i++) {
    const gx = ((fr(i * 3 + 501) * width) + Math.sin(K.t * .011 + i) * u * .004 + width) % width;
    const gy2 = fr(i * 3 + 502) * height;
    fill(hw(st.rock[0] + ho), st.rock[1] * .5, fr(i * 3 + 503) > .5 ? 96 : 4, 3 + fr(i) * 7);
    rect(gx, gy2, u * .0016, u * .0016);
  }
}

// --- vignette / plate edge ---
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .055);
  stroke(hw(st.rock[0] + ho), st.rock[1], st.wire ? st.skyT[2] : 8, (st.grain > 40 ? 30 : 18) * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();

if (P.alpha < 1) { fill(hw(st.rock[0] + ho), st.rock[1] * .5, 5, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
